<?php require_once __DIR__.'/../includes/functions.php';require_once __DIR__.'/includes/content.php';$pdo=get_db();$pageTitle='Hasil Polling NEXADIPTA 21';$activePage='results';$polls=$pdo->query("SELECT id,title,poll_type FROM polls ORDER BY id DESC")->fetchAll();$results=[];foreach($polls as $p){$s=get_poll_settings((int)$p['id']);if(empty($s['show_results']))continue;$results[]=['poll'=>$p,'rows'=>$p['poll_type']==='questionnaire'?get_questionnaire_result_rows((int)$p['id']):get_public_poll_result_rows((int)$p['id'])];}include __DIR__.'/includes/header.php';?><section class="page-hero"><div class="container"><span class="section-kicker">HASIL POLLING</span><h1>Hasil dapat dilihat tanpa login.</h1><p>Hanya polling yang sudah dibuka untuk publik oleh panitia yang ditampilkan.</p></div></section><section class="section"><div class="container results-list"><?php if(!$results):?><div class="empty-card">Belum ada hasil polling yang dibuka untuk publik.</div><?php endif;foreach($results as $item):$p=$item['poll'];$rows=$item['rows'];if($p['poll_type']==='questionnaire'):?><article class="result-card"><span class="poll-status">QUESTIONNAIRE</span><h3><?=e($p['title'])?></h3><?php foreach($rows as $q):$qt=0;foreach($q['options'] as $o)$qt+=(int)$o['vote_count'];?><div class="mini-question"><h4><?=e($q['question'])?></h4><?php foreach($q['options'] as $o):$pct=$qt?round(((int)$o['vote_count']/$qt)*100,1):0;?><div class="chart-row"><div class="chart-label"><?=e($o['option_text'])?></div><div class="chart-track"><div class="chart-fill" style="width:<?=max($pct,$o['vote_count']>0?4:0)?>%"><?=$pct?>%</div></div><div class="chart-count"><?=(int)$o['vote_count']?></div></div><?php endforeach;?></div><?php endforeach;?></article><?php else:$total=0;foreach($rows as $r)$total+=(int)$r['vote_count'];?><article class="result-card"><span class="poll-status">HASIL POLLING</span><h3><?=e($p['title'])?></h3><p class="result-total">Total vote: <strong><?=$total?></strong></p><?php foreach($rows as $r):$pct=$total?round(((int)$r['vote_count']/$total)*100,1):0;?><div class="chart-row"><div class="chart-label"><?=e($r['name'])?></div><div class="chart-track"><div class="chart-fill" style="width:<?=max($pct,$r['vote_count']>0?4:0)?>%"><?=$pct?>%</div></div><div class="chart-count"><?= (int)$r['vote_count']?></div></div><?php endforeach;?></article><?php endif;endforeach;?></div></section><?php include __DIR__.'/includes/footer.php';?>
